= true\"\n    @slide-move=\"pressed = true\"\n    @slide-end=\"pressed = false\"\n  >\n    <SliderTrack\n      :class=\"\n        cn(\n          'relative h-2.5 w-full grow cursor-pointer overflow-visible rounded-full',\n          'before:absolute before:-inset-2 before:block before:bg-transparent'\n        )\n      \"\n      :style=\"{ background: gradient }\"\n    >\n      <SliderThumb\n        :class=\"\n          cn(\n            'top-1/2 block size-4 shrink-0 cursor-grab rounded-full shadow-md ring-1 ring-black/25',\n            'transition-[color,box-shadow,background-color]',\n            'before:absolute before:-inset-1.5 before:block before:rounded-full before:bg-transparent',\n            'hover:ring-2 hover:ring-black/40 focus-visible:ring-2 focus-visible:ring-black/40 focus-visible:outline-hidden',\n            'disabled:pointer-events-none disabled:opacity-50',\n            { 'cursor-grabbing': pressed }\n          )\n        \"\n        :style=\"{ backgroundColor: thumbColor }\"\n        :aria-label\n      />\n    </SliderTrack>\n  </SliderRoot>\n</template>\n","import { computed, toValue } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\n\ninterface NumberWidgetOptions {\n  step?: number\n  step2?: number\n  precision?: number\n}\n\n/**\n * Shared composable for calculating step values in number input widgets\n * Handles both explicit step2 values and precision-derived steps\n */\nexport function useNumberStepCalculation(\n  options: NumberWidgetOptions | undefined,\n  precisionArg: MaybeRefOrGetter<number | undefined>,\n  returnUndefinedForDefault = false\n) {\n  return computed(() => {\n    const precision = toValue(precisionArg)\n    // Use step2 (correct input spec value) if available\n    if (options?.step2 !== undefined) {\n      return options.step2\n    }\n    // Use step / 10 for custom large step values (> 10) to match litegraph behavior\n    // This is important for extensions like Impact Pack that use custom step values (e.g., 640)\n    // We skip default step values (1, 10) to avoid affecting normal widgets\n    const step = options?.step\n    if (step !== undefined && step > 10) {\n      return step / 10\n    }\n\n    if (precision === undefined) {\n      return returnUndefinedForDefault ? undefined : 0\n    }\n\n    if (precision === 0) return 1\n\n    // For precision > 0, step = 1 / (10^precision)\n    const calculatedStep = 1 / Math.pow(10, precision)\n    return returnUndefinedForDefault\n      ? calculatedStep\n      : Number(calculatedStep.toFixed(precision))\n  })\n}\n","<template>\n  <WidgetLayoutField :widget=\"widget\">\n    <div\n      :class=\"\n        cn(\n          WidgetInputBaseClass,\n          'flex items-center gap-2 pr-2 pl-3',\n          useWidgetHeight()\n        )\n      \"\n    >\n      <GradientSlider\n        v-model=\"modelValue\"\n        :stops=\"gradientStops\"\n        :min=\"widget.options?.min ?? 0\"\n        :max=\"widget.options?.max ?? 100\"\n        :step=\"stepValue\"\n        :disabled=\"widget.options?.disabled\"\n        :aria-label=\"widget.name\"\n        class=\"min-w-0 flex-1\"\n      />\n      <NumberField\n        v-model=\"modelValue\"\n        :step=\"stepValue\"\n        :min=\"widget.options?.min\"\n        :max=\"widget.options?.max\"\n        :disabled=\"widget.options?.disabled\"\n        :format-options=\"{\n          minimumFractionDigits: precision,\n          maximumFractionDigits: precision\n        }\"\n        class=\"h-auto w-16 shrink-0 bg-transparent hover:bg-transparent\"\n      >\n        <NumberFieldInput :aria-label=\"widget.name\" class=\"text-xs\" />\n      </NumberField>\n    </div>\n  </WidgetLayoutField>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport GradientSlider from '@/components/gradientslider/GradientSlider.vue'\nimport NumberField from '@/components/ui/number-field/NumberField.vue'\nimport NumberFieldInput from '@/components/ui/number-field/NumberFieldInput.vue'\nimport type { ColorStop } from '@/lib/litegraph/src/interfaces'\nimport type { IWidgetGradientSliderOptions } from '@/lib/litegraph/src/types/widgets'\nimport type { SimplifiedWidget } from '@/types/simplifiedWidget'\nimport { useWidgetHeight } from '@/types/widgetTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { useNumberStepCalculation } from '../composables/useNumberStepCalculation'\nimport { WidgetInputBaseClass } from './layout'\nimport WidgetLayoutField from './layout/WidgetLayoutField.vue'\n\nconst DEFAULT_GRADIENT_STOPS: ColorStop[] = [\n  { offset: 0, color: [0, 0, 0] },\n  { offset: 1, color: [255, 255, 255] }\n]\n\nconst { widget } = defineProps<{\n  widget: SimplifiedWidget<number, IWidgetGradientSliderOptions>\n}>()\n\nconst modelValue = defineModel<number>({ default: 0 })\n\nconst gradientStops = computed<ColorStop[]>(() => {\n  const stops = widget.options?.gradient_stops\n  if (stops && stops.length >= 2) return stops\n  return DEFAULT_GRADIENT_STOPS\n})\n\nconst precision = computed(() => {\n  const p = widget.options?.precision\n  return typeof p === 'number' && p >= 0 ? p : undefined\n})\n\nconst stepValue = useNumberStepCalculation(widget.options, precision, true)\n</script>\n","<template>\n  <WidgetLayoutField :widget=\"widget\">\n    <div\n      :class=\"\n        cn(\n          WidgetInputBaseClass,\n          'flex items-center gap-2 pr-2 pl-3',\n          useWidgetHeight()\n        )\n      \"\n    >\n      <GradientSlider\n        v-model=\"modelValue\"\n        :stops=\"gradientStops\"\n        :min=\"widget.options?.min ?? 0\"\n        :max=\"widget.options?.max ?? 100\"\n        :step=\"stepValue\"\n        :disabled=\"widget.options?.disabled\"\n        :aria-label=\"widget.name\"\n        class=\"min-w-0 flex-1\"\n      />\n      <NumberField\n        v-model=\"modelValue\"\n        :step=\"stepValue\"\n        :min=\"widget.options?.min\"\n        :max=\"widget.options?.max\"\n        :disabled=\"widget.options?.disabled\"\n   